// src/data/curriculum/availability.js
// ─────────────────────────────────────────────────────────────────────────────
// GENERATED by scripts/curriculum/build-manifest.mjs from provenance.json — do not edit by hand.
//
// Datasets that stay in topics.js for students who already selected them, but are NOT offered
// when someone picks a new subject (curriculumSupport.getSupportedSubjects). A dataset lands here
// only when official evidence shows the board does not offer that qualification (status
// UNSUPPORTED), so RevisionFlow never presents it as a supported curriculum.
//
// Dataset id format: board|qualification|subject  (board = canonical stored value, e.g. WJEC).
// ─────────────────────────────────────────────────────────────────────────────

export const LEGACY_DATASET_IDS = new Set([
  "AQA|A-Level|Classical Greek",
  "AQA|A-Level|Latin",
  "AQA|AS-Level|Accounting",
  "AQA|AS-Level|Art & Design",
  "AQA|AS-Level|Classical Greek",
  "AQA|AS-Level|Design and Technology: Product Design",
  "AQA|AS-Level|Drama and Theatre",
  "AQA|AS-Level|English Language & Literature",
  "AQA|AS-Level|Environmental Science",
  "AQA|AS-Level|Latin",
  "AQA|AS-Level|Law",
  "AQA|AS-Level|Media Studies",
  "AQA|AS-Level|Music",
  "AQA|AS-Level|Philosophy",
  "AQA|AS-Level|Photography",
  "AQA|AS-Level|Physical Education",
  "AQA|AS-Level|Politics",
  "AQA|GCSE|Arabic",
  "AQA|GCSE|Film Studies",
])

export function isLegacyDataset(board, qualification, subject) {
  return LEGACY_DATASET_IDS.has(board + '|' + qualification + '|' + subject)
}
